normalize=()=>{baseNormalize();const d=defaults();state.settings={...d.settings,...state.settings};state.weather={...d.weather,...state.weather};state.social={...d.social,...state.social};for(const k of ['redbook','weibo'])if(!Array.isArray(state.social[k]))state.social[k]=d.social[k];if(!Array.isArray(state.webpages))state.webpages=d.webpages;if(!Array.isArray(state.callHistory))state.callHistory=[];state.story={...d.story,...state.story};if(!Array.isArray(state.story.nodes))state.story.nodes=[];if(!Array.isArray(state.story.done))state.story.done=[];state.baiduHistory=Array.isArray(state.baiduHistory)?state.baiduHistory.filter(x=>typeof x==='string').map(x=>x.slice(0,160)).slice(0,100):d.baiduHistory;state.widgetPhoto=state.widgetPhoto||'';state.appIcons=state.appIcons&&typeof state.appIcons==='object'&&!Array.isArray(state.appIcons)?state.appIcons:{};for(const [id,icon] of Object.entries(state.appIcons)){if(!icon||typeof icon.data!=='string'||!/^data:image\/(jpeg|png|webp);base64,/.test(icon.data)){delete state.appIcons[id];continue}icon.zoom=Math.min(1.6,Math.max(1,Number(icon.zoom)||1))}if(!/^(\d{4}|\d{6})$/.test(state.settings.pin))state.settings.pin=''};
